/* Version script for stub.c: Linux-PAM 1.3.1's LIBPAM_1.0 node, limited to
   the calls qshd makes. Linux-PAM 1.4 added the LIBPAM_1.4 node
   (pam_start_confdir); it is deliberately absent here. */
LIBPAM_1.0 {
  global:
    pam_start;
    pam_end;
    pam_acct_mgmt;
    pam_open_session;
    pam_close_session;
    pam_setcred;
    pam_set_item;
    pam_getenvlist;
    pam_strerror;
};
